import {WEAPONS} from './combat.js';
import {activeLanguage,translate} from './i18n.js';
import {distance} from './math.js';
export const CHARACTERS=[
 ['Polat','Gündüzleri kurye. Ailesinin güvenliği için kendi sınırlarını zorlayan bir İstanbullu.','A courier forced to test his limits to protect his family.'],
 ['Elif','Tarihi yapıların onarımıyla uğraşan mimar. Polatın hayalini değil, gerçeğini paylaşmak istiyor.','An architect restoring old buildings. She wants a place in Polat’s real life, not only his dreams.'],
 ['Reyhan','Polatın annesi. Ailenin korkusunu saklamak yerine birbirlerine anlatmalarını savunuyor.','Polat’s mother, determined that fear must not divide the family.'],
 ['Murat','Polatın babası. Eski bir matbaacı; Karanın sahte şirketleriyle ilgili kayıtları buldu.','Polat’s father, a printer who found records of Karan’s shell companies.'],
 ['Deniz','Çocukluk arkadaşı ve tamirci. İnsanların da motorlar gibi dinlenmeye ihtiyacı olduğuna inanıyor.','A childhood friend and mechanic who knows people need repairs too.'],
 ['Selim','Gazeteci. Kanıtı yayımlamak için kaynağını hayatta tutması gerekiyor.','A journalist who must keep his source alive to publish the evidence.'],
 ['Zeynep','Klinik işleten doktor; yaralıları iyileştirirken mahallenin hafızasını da tutuyor.','A doctor whose clinic protects both injured neighbors and their stories.'],
 ['Mert','Nevâ Lokantasının sahibi. Mahallesini Karana bırakmak istemiyor.','Owner of Neva Restaurant, refusing to surrender his neighborhood.'],
 ['Baran','Karanın eski adamı. Kefaret arayışı bazen korkusuyla çatışıyor.','A former Karan enforcer, torn between fear and a chance at redemption.'],
 ['Cem','Özel harekât komiseri. Sokakta gördüğü ile dosyada okuduğu aynı hikâye değil.','A SWAT commander who sees a different story on the street than in his files.'],
 ['Orhan Karan','Borç ve tehdit ağıyla güç kazanan kurgusal suç lideri.','A fictional crime boss whose influence depends on debts and intimidation.']
];
const chapter=(title,en,location,kind,reward,pages,extra={})=>({title,en,location,kind,reward,pages,...extra});
export const CHAPTERS=[
 chapter('Sabah Vardiyası','Morning Shift','restaurant','meet',400,[['Polat','Sabahın ilk vapuru, annemin çayı, Elifin bir gün yapacağız dediği sahil yürüyüşü. Benim hayatım bunlardan ibaretti.','The first ferry, my mother’s tea, the walk Elif kept promising. That used to be my whole world.'],['Mert','Paketler yetişti. Babanı gördüm; yine matbaadan kalan kutuları taşıyordu. Bu akşam ailece gelin.','The delivery is on time. I saw your father carrying old print-shop boxes. Bring the family tonight.'],['Polat','O gün mahalleyi ezbere bildiğimi sanıyordum. Meğer insan, korktuğu bir sokağı yeniden öğreniyormuş.','I thought I knew every street. Fear would teach me the neighborhood all over again.']]),
 chapter('Kapıdaki Zarf','The Envelope','home','meet',500,[['Reyhan','Bunu kapının altından attılar. Paradan söz etmiyorlar, babanın bulduğu defterden söz ediyorlar.','They pushed this under the door. It is not about money. They want the ledger your father found.'],['Murat','Orhan Karanın şirketleri bizim sokağı da satın almış gibi davranıyor. Defterde gerçek sahiplerin imzaları var.','Karan’s companies act as if they own our street. The ledger holds signatures of the actual owners.'],['Polat','Ben normal bir insandım. Ama normal hayatımızı tehdit edenlerin gücü, herkesin susmasına dayanıyordu.','I was an ordinary man. Their power depended on ordinary people staying silent.']]),
 chapter('Elifin Çizgileri','Elif’s Drawings','elif','meet',550,[['Elif','Şu duvarı kaldırınca deniz görünüyor. Bir gün kitaplarla dolu küçük bir kafe olacak burası. Ama önce bana gerçeği anlat.','Remove this wall and you can see the sea. One day this will be a little book cafe. First, tell me the truth.'],['Polat','Sana korkmadığımı söylemek istiyorum. Aslında seni bu korkunun dışında tutmak istiyorum.','I want to tell you I am not afraid. Really, I want to keep you outside my fear.'],['Elif','Beni korumak, beni hikâyenden silmek değildir. Babanın kayıtlarını birlikte kurtaracağız.','Protecting me does not mean erasing me from your story. We will save your father’s records together.']],{dream:true,choice:true}),
 chapter('Eski Dost, Yeni Motor','Old Friend, New Engine','mechanic','meet',650,[['Deniz','Arabayı tamir ederim. Seni de dinlerim. Ama intikamla adalet arasındaki farkı sen bileceksin.','I can fix the car, and I can listen. You must know the difference between revenge and justice.'],['Polat','Ailemi kurtarmak için Karanın para akışını kesmem gerekiyor. Önce limandaki defter.','To protect my family I have to break Karan’s network. The dock ledger comes first.'],['Deniz','Arka cam savunması artık sen basınca ateş eder. Şehirde robot taretle gezilmez. Yaya kalırsan da sakin nişan al.','Rear-window defense fires only when you press it. No robot turret. If you must go on foot, aim calmly.']],{unlock:'shotgun'}),
 chapter('Limanın Sessizliği','Silence at the Dock','warehouse','clear',1000,[['Baran','Benim adımı duymadın. Depodaki kayıtlar bu akşam taşınacak. İçerideki adamlar teslim olmak istemeyecek.','You never heard my name. The warehouse records move tonight. The guards will not welcome you.'],['Polat','Defteri almak başka, o defterin bedelini bir başkasına ödetmek başka. Buradan kanıtla çıkacağım.','Taking a ledger is one thing. Making someone else pay for it is another. I leave with evidence.']],{count:4}),
 chapter('Kırık Frekans','Broken Frequency','press','meet',850,[['Selim','Defter tek başına yetmez. Nakliye kodlarıyla belediye arşivindeki sözleşmeler eşleşiyor.','The ledger alone is not enough. Shipping codes match contracts in the public archive.'],['Polat','Babamı susturmak için bütün ailemi tehdit ettiler. Sen bunu yayımlayabilir misin?','They threatened my family to silence my father. Can you publish this?'],['Selim','Yayımlarız. Ama tanıkları da korumamız gerek. Elifin restorasyon dosyası bize ikinci bir iz verdi.','We can. We must protect the witnesses. Elif’s restoration files gave us another lead.']]),
 chapter('Nevâ Lokantası','Neva Restaurant','restaurant','defend',1400,[['Mert','Kepenkleri indirdim ama komşular içeride. Karanın adamları arka sokakta toplandı.','The shutters are down, but the neighbors are inside. Karan’s men are gathering outside.'],['Polat','Masaları siper yap. Kapıyı göreceğim bir yerde duracağım. Yardım gelene kadar burayı bırakmıyoruz.','Use the tables as cover. I will watch the entrance. We hold until help arrives.'],['Elif','Polat, beni duyuyor musun? Zeynep arka kapıdan insanları çıkarıyor. Yaşaman gerekiyor.','Polat, can you hear me? Zeynep is moving people out. You have to stay alive.']],{duration:45,count:3}),
 chapter('Gönderilmeyen Mektup','The Unsent Letter','cafe','meet',900,[['Polat','Gece olunca Elifi aynı masada hayal ediyorum. Ben kapıya bakmıyorum, o telefonun çalmasından korkmuyor.','At night I picture Elif at this table. I am not watching the door. She is not afraid of the phone.'],['Elif','Bana geleceğimizi yalnız rüyanda anlatma. Bugün için küçük bir söz ver: kaybolmayacaksın.','Do not tell me about our future only in dreams. Promise something small today: you will not disappear.'],['Polat','Bazen seni düşünmek beni bu şehre bağlıyor. Bazen de bu şehri bitirmeden sana dönemeyeceğimi sanıyorum.','Sometimes thinking of you anchors me here. Sometimes I think I cannot return until I finish this.'],['Elif','Bir şehri bitiremezsin. Ama birinin kurduğu korku düzenini bozabilirsin. Sonra eve dönersin.','You cannot finish a city. You can break one man’s rule of fear. Then you come home.']],{dream:true,choice:true}),
 chapter('Tahsildarın Hesabı','The Collector’s Account','club','clear',1600,[['Baran','Kulübün kasası yalnız para tutmuyor. Mahallenin borçları da orada. Benim adım da o dosyalarda.','The club safe holds more than cash. It holds the neighborhood’s debts. My name is in those files too.'],['Polat','Bize yardım etmenin bedeli var. Ama korkuyla yaşamaya devam etmenin de var.','Helping us has a price. So does continuing to live in fear.'],['Baran','Bu kez kaçmayacağım. Dosyaları aldığında Selime götür.','This time I will not run. Take the files to Selim.']],{count:5,unlock:'smg'}),
 chapter('Köprüde Son Işık','Last Light by the Bridge','shore','escape',1400,[['Cem','Merkez seni silahlı saldırgan olarak bildiriyor. Ama aynı sokakta yardım isteyen insanları da görüyorum.','Dispatch calls you an armed suspect. I also see people asking you for help.'],['Polat','Bana inanmanı istemiyorum. Dosyalara bakmanı istiyorum.','I am not asking you to believe me. Look at the files.'],['Cem','Önce sokaktaki takibi atlat. Şimdi burada konuşamayız.','Lose the pursuit first. We cannot talk here.']],{stars:3}),
 chapter('İçerideki Adam','The Inside Man','press','meet',1200,[['Selim','Baranın ifadesi kayıtlarla uyuşuyor. Ama Karanın para aktardığı hesaplardan biri boşaltıldı.','Baran’s testimony matches. But one of Karan’s accounts has just been emptied.'],['Elif','Kafe projesini incelerken bir bodrum planı buldum. Depodan kulübe uzanan servis geçidini gizlemişler.','I found an old basement plan in the cafe project. They concealed a service passage to the club.'],['Polat','Sen benim kurtaracağım bir hayal değilsin Elif. Beni ayakta tutan gerçek sensin.','You are not a dream I have to rescue, Elif. You are what keeps me standing.']],{choice:true}),
 chapter('Dört Yıldız','Four Stars','shore','escape',1800,[['Deniz','Özel ekipler yola çıktı. Düz yolda nitroyla arayı aç; helikopter sonsuza kadar yetişemez. Sonra kapalı hana gir.','SWAT is coming. Boost down a clear road; the helicopter cannot keep up forever. Then use a covered passage.'],['Polat','Bu kez yalnız kendim için kaçmıyorum. Kayıtların ulaşması için yaşıyorum.','This time I am not running only for myself. The records have to survive.']],{stars:4}),
 chapter('Sessiz Operasyon','Quiet Operation','warehouse','clear',1900,[['Baran','Geçidin kapısını açtım. İçeride Karanın son sevkiyat kayıtları var. Arkada bırakacağım bir hayatım kalmadı.','I opened the passage. The last shipment records are inside. I have no old life left to return to.'],['Polat','Hâlâ var. Bu geceyi atlatalım, sonra ne yapacağına kendin karar verirsin.','You still have a life. Survive tonight, then decide what to do with it.']],{count:6,unlock:'carbine'}),
 chapter('Kayıt Dışı','Off the Record','clinic','meet',1400,[['Zeynep','Selimi burada sakladık. Yaraları kapanıyor. İnsanların korkusu daha yavaş iyileşiyor.','Selim is safe here. His wounds are closing. Fear heals more slowly.'],['Selim','Yayın hazır. Cem belgeleri bağımsız bir savcıya ulaştıracak. Babanın da ifade vermesi gerekiyor.','The report is ready. Cem will take the documents to an independent prosecutor. Your father must testify.'],['Polat','Onu bu işe ben sokmadım. Ama onu buradan çıkarmadan bitirmiş sayılmam.','I did not bring him into this. But I am not finished until I bring him out.']]),
 chapter('Kırılan Ev','The Broken Home','home','clear',2200,[['Reyhan','Evimizin kapısını kırabilirler. Birbirimize olan güvenimizi kıramazlar. Babanı arka odaya götürdüm.','They can break our door. They cannot break our trust in one another. Your father is in the back room.'],['Polat','Anne, pencereye yaklaşma. Bu geceden sonra sizi her sabah korkuyla uyandıran telefon susacak.','Stay away from the window, Mom. After tonight, that phone will stop waking you in fear.']],{count:5}),
 chapter('Galata Gecesi','Galata Night','restaurant','defend',2400,[['Mert','Yayın başlayınca herkes buraya geldi. Bu kez yalnız lokantayı değil, bütün mahallenin tanıklığını koruyoruz.','Everyone came here when the report aired. We are protecting the neighborhood’s testimony now.'],['Cem','Ekibimde dosyayı görmemiş olanlar var. Ateş hattından uzak durun. Silah sesleri gerçeği boğmasın.','Some of my unit have not seen the files. Keep people out of the crossfire. Do not let gunfire drown the truth.'],['Elif','Sabah olunca denize bakan masayı ayıracağım. Sakın bana yine bir mektup bırakma. Kendin gel.','I will keep the table facing the sea. Do not leave another letter. Come yourself.']],{duration:65,count:4,stars:4}),
 chapter('Sabaha Karşı','Before Dawn','club','clear',3200,[['Karan','Ben gidersem bu şehirde hiçbir şey değişmez sanıyorsun. İnsanların borcunu ben yaratmadım.','You think anything changes if I leave? I did not invent their debts.'],['Polat','Borcu sen yaratmadın. Ama insanların birbirine güvenmesini engelleyen korkuyu sen besledin.','You did not invent debt. You fed the fear that stopped people trusting each other.'],['Elif','Kanıtın yedeği bende. Bu hikâyenin sonunu tek başına taşımana gerek yok.','I have a copy of the evidence. You do not have to carry the ending alone.']],{count:7,boss:true,unlock:'marksman'}),
 chapter('Elifin Sabahı','Elif’s Morning','cafe','final',4000,[['Polat','Sabah vapuru yine aynı saatte geçiyor. Bu kez annem telefonu sessize almıyor. Babam matbaaya dönmeyi düşünüyor.','The morning ferry passes at the same time. Mom no longer silences her phone. Dad is thinking of reopening the print shop.'],['Elif','Kafe için ilk rafı çizdim. İkinci rafta senin sevdiğin kitaplara yer ayırdım. Artık hayal kurmak için uyumana gerek yok.','I drew the first bookshelf. The second has room for your favorite books. You no longer need sleep to dream.'],['Polat','Onu hep uzak bir gelecekte hayal etmiştim. Meğer dönmem gereken yer, yanındaki boş sandalyeymiş.','I always imagined her in a distant future. All along, the place I had to return to was the empty chair beside her.']],{dream:true,choice:true})
];
export function newStoryState(v={}){v=v&&typeof v==='object'?v:{};return {index:Math.max(0,Math.min(CHAPTERS.length,Math.floor(Number(v.index)||0))),trust:Math.max(-20,Math.min(20,Number(v.trust)||0)),completed:Array.isArray(v.completed)?v.completed.slice(0,18):[],jobs:Math.max(0,Math.floor(Number(v.jobs)||0)),ending:v.ending||null};}
export const STREET_JOBS=[{id:'food',tr:'Sıcak Yemek',en:'Hot Food',from:'restaurant',to:'clinic',reward:260},{id:'courier',tr:'Mahalle Kuryesi',en:'Local Courier',from:'press',to:'mechanic',reward:320},{id:'taxi',tr:'Gece Yolcusu',en:'Night Passenger',from:'cafe',to:'shore',reward:380},{id:'repair',tr:'Yedek Parça',en:'Spare Parts',from:'mechanic',to:'home',reward:300}];
export class StoryDirector{
 constructor(sim,state){this.sim=sim;this.state=newStoryState(state);this.phase='travel';this.timer=0;this.wave=0;this.pending=null;this.job=null;this.announced=false;}
 current(){return CHAPTERS[this.state.index]||null;}
 location(id){return this.sim.world.locations.find(l=>l.id===id);}
 text(m,key='title'){return activeLanguage==='en'?(m.en||m[key]):m[key];}
 target(){return this.location(this.job?(this.job.picked?this.job.to:this.job.from):this.current()?.location);}
 objective(){const m=this.current();if(this.job)return {title:this.text(this.job,'tr'),desc:(activeLanguage==='en'?'Deliver to ':'Teslimat: ')+translate(this.target()?.name||''),progress:this.job.picked?1:0,total:2};if(!m)return {title:activeLanguage==='en'?'A new morning':'Yeni bir sabah',desc:activeLanguage==='en'?'Explore, take jobs, and build your future.':'Şehri keşfet, işler al ve yeni hayatını kur.',progress:18,total:18};let desc=this.target()?.name||'';if(this.phase==='battle')desc+=(m.kind==='defend'?' · '+Math.ceil(Math.max(0,m.duration-this.timer))+(activeLanguage==='en'?' s':' sn'):' · '+this.sim.human.people.filter(p=>p.alive&&p.encounter==='chapter'+this.state.index).length+(activeLanguage==='en'?' targets':' hedef'));else if(this.phase==='escape')desc=activeLanguage==='en'?'Lose the cops, then return to the meeting point.':'Takibi atlat ve buluşma noktasına geri dön.';else desc+=(activeLanguage==='en'?' · F exit car · E enter / talk':' · F araçtan in · E gir / konuş');return {title:(this.state.index+1)+'. '+this.text(m),desc,progress:this.phase==='battle'&&m.kind==='defend'?this.timer:this.state.index,total:this.phase==='battle'&&m.kind==='defend'?m.duration:18};}
 dialogue(pages,action,choices=false,dream=false){if(this.pending)return;this.pending=action;this.pendingChoice=choices;this.sim.event('dialogue',{pages,choices,dream});}
 interact(id){if(this.job&&id===(this.job.picked?this.job.to:this.job.from)){if(!this.job.picked){this.job.picked=true;this.sim.event('toast',{text:activeLanguage==='en'?'DELIVERY PICKED UP':'TESLİMAT ALINDI'});}else{this.state.jobs++;this.sim.event('story-save',{state:this.state,reward:this.job.reward});this.job=null;}return;}if(this.sim.mode!=='story')return;const m=this.current();if(!m||m.location!==id||this.pending)return;if(this.phase==='travel')this.dialogue(m.pages,m.kind==='clear'||m.kind==='defend'?'battle':m.kind==='escape'?'escape':'complete',!!m.choice,!!m.dream);else if(this.phase==='return')this.complete();}
 interactNearby(){const target=this.target();if(target&&distance(target,this.sim.player)<180)this.interact(target.id);}
 resolve(choice=0){const action=this.pending;this.pending=null;if(!action)return;if(this.pendingChoice)this.state.trust+=choice===0?1:-1;this.pendingChoice=false;const m=this.current();if(action==='battle'){this.phase='battle';this.timer=0;this.wave=0;this.sim.human.encounter(m.count||4,'mafia','chapter'+this.state.index);if(m.boss){const boss=this.sim.human.people.filter(p=>p.encounter==='chapter'+this.state.index)[0];if(boss){boss.hp=boss.maxHp=340;boss.armor=80;boss.weapon='carbine';}}if(m.stars)this.sim.human.raiseWanted(m.stars);}else if(action==='escape'){this.phase='escape';this.sim.human.raiseWanted(m.stars||3);if(this.sim.human.interior)this.sim.human.leave();}else this.complete(choice);}
 complete(choice=0){const m=this.current();if(!m)return;this.state.completed.push({title:m.title,en:m.en});if(m.unlock){const a=this.sim.human.armory[m.unlock];a.owned=true;a.ammo=180;this.sim.human.clip[m.unlock]=Math.min(WEAPONS.find(w=>w.id===m.unlock)?.mag||12,180);this.sim.event('armory-save',{armory:this.sim.human.armory});}if(m.kind==='final')this.state.ending=this.state.trust>=2&&choice===0?'together':'rebuilding';this.state.index++;this.phase='travel';this.sim.score+=m.reward;this.sim.event('story-save',{state:this.state,reward:m.reward});this.sim.event('toast',{text:(activeLanguage==='en'?'CHAPTER COMPLETE · ₺':'BÖLÜM TAMAM · ₺')+m.reward});}
 startJob(id){const j=STREET_JOBS.find(j=>j.id===id);if(j){this.job={...j,picked:false};this.sim.event('toast',{text:activeLanguage==='en'?'JOB ACCEPTED · CHECK THE MAP':'İŞ ALINDI · HARİTAYA BAK'});}}
 update(dt){if(this.sim.mode!=='story')return;const m=this.current();if(!m)return;const h=this.sim.human;if(this.phase==='battle'&&h.scene()===m.location){this.timer+=dt;if(m.kind==='defend'&&Math.floor(this.timer/15)>this.wave&&this.timer<m.duration){this.wave=Math.floor(this.timer/15);if(h.people.filter(p=>p.alive&&p.encounter==='chapter'+this.state.index).length<5)h.encounter(2,'mafia','chapter'+this.state.index);}const alive=h.people.some(p=>p.alive&&p.encounter==='chapter'+this.state.index);if((m.kind==='defend'&&this.timer>=m.duration)||m.kind==='clear'&&!alive&&this.timer>2){this.phase='return';this.dialogue([['Polat','Kanıtları aldık. Şimdi eve dönecek bir yol bulmalıyım.','We have the evidence. Now I need a way home.']],'complete');}}if(this.phase==='escape'&&!this.sim.pursuit&&distance(h.pursuitPosition(),this.target())<240)this.complete();}
}
